package pdfgen

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	MaxUploadSize  = 10 << 20 // 10MB
	UploadDir      = "/var/lib/pdfgen/assets"
	ServiceSecret  = "k8s-internal-shared-secret-2024"
	TokenValidSecs = 300
)

var allowedExtensions = map[string]bool{
	".png":  true,
	".jpg":  true,
	".jpeg": true,
	".svg":  true,
	".ttf":  true,
	".otf":  true,
}

var allowedMimeTypes = map[string]bool{
	"image/png":                true,
	"image/jpeg":               true,
	"image/svg+xml":            true,
	"font/ttf":                 true,
	"font/otf":                 true,
	"application/octet-stream": true,
}

type AssetUploadHandler struct {
	basePath string
}

func NewAssetUploadHandler(basePath string) *AssetUploadHandler {
	if basePath == "" {
		basePath = UploadDir
	}
	return &AssetUploadHandler{basePath: basePath}
}

func (h *AssetUploadHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !h.validateServiceToken(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	category := r.URL.Query().Get("category")
	if !h.isValidCategory(category) {
		http.Error(w, "Invalid category", http.StatusBadRequest)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, MaxUploadSize)
	if err := r.ParseMultipartForm(MaxUploadSize); err != nil {
		http.Error(w, "File too large", http.StatusRequestEntityTooLarge)
		return
	}

	file, header, err := r.FormFile("asset")
	if err != nil {
		http.Error(w, "Invalid file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	filename := header.Filename
	ext := strings.ToLower(filepath.Ext(filename))
	if !allowedExtensions[ext] {
		http.Error(w, "File type not allowed", http.StatusBadRequest)
		return
	}

	buf := make([]byte, 512)
	n, err := file.Read(buf)
	if err != nil && err != io.EOF {
		http.Error(w, "Cannot read file", http.StatusInternalServerError)
		return
	}
	mimeType := http.DetectContentType(buf[:n])
	if !allowedMimeTypes[mimeType] {
		http.Error(w, "MIME type not allowed", http.StatusBadRequest)
		return
	}
	file.Seek(0, io.SeekStart)

	sanitized := h.sanitizeFilename(filename)
	destPath := h.buildDestPath(category, sanitized)

	if err := os.MkdirAll(filepath.Dir(destPath), 0750); err != nil {
		http.Error(w, "Storage error", http.StatusInternalServerError)
		return
	}

	dst, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0640)
	if err != nil {
		http.Error(w, "Cannot create file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "{\"path\": \"%s\"}\n", destPath)
}

func (h *AssetUploadHandler) validateServiceToken(r *http.Request) bool {
	authHeader := r.Header.Get("X-Service-Auth")
	parts := strings.SplitN(authHeader, ":", 2)
	if len(parts) != 2 {
		return false
	}

	timestampStr := parts[0]
	providedSig := parts[1]

	mac := hmac.New(sha256.New, []byte(ServiceSecret))
	mac.Write([]byte(timestampStr))
	expectedSig := hex.EncodeToString(mac.Sum(nil))

	if !hmac.Equal([]byte(providedSig), []byte(expectedSig)) {
		return false
	}

	var ts int64
	fmt.Sscanf(timestampStr, "%d", &ts)
	now := time.Now().Unix()
	if now-ts > TokenValidSecs || ts-now > TokenValidSecs {
		return false
	}

	return true
}

func (h *AssetUploadHandler) isValidCategory(cat string) bool {
	valid := []string{"fonts", "images", "templates", "logos"}
	for _, v := range valid {
		if v == cat {
			return true
		}
	}
	return false
}

func (h *AssetUploadHandler) sanitizeFilename(name string) string {
	name = filepath.Base(name)
	name = strings.ReplaceAll(name, "..", "")
	name = strings.Map(func(r rune) rune {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == '.' || r == '-' || r == '_' {
			return r
		}
		return '_'
	}, name)
	return name
}

func (h *AssetUploadHandler) buildDestPath(category, filename string) string {
	return filepath.Join(h.basePath, category, filename)
}
